-- LOCAL TEST FIXTURE ONLY. Supabase auth.uid is represented by a claim stub.
-- No real accounts or remote services. Do not run in an existing project.
CREATE TABLE public.majice (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 model text NOT NULL, boja text, velicina text, kolicina smallint,
 minimalna_kolicina integer NOT NULL DEFAULT 0,
 CONSTRAINT majice_minimalna_kolicina_check CHECK(minimalna_kolicina>=0)
);
CREATE TABLE public.lager_urednici (
 user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX majice_jedinstvena_stavka ON public.majice
 (lower(trim(model)), lower(trim(boja)), upper(trim(velicina)));
CREATE FUNCTION public.dodaj_majice(p_model text, p_boja text, p_velicina text, p_kolicina integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF p_model IS NULL OR trim(p_model) = ''
     OR p_boja IS NULL OR trim(p_boja) = ''
     OR p_velicina IS NULL OR trim(p_velicina) = ''
     OR p_kolicina IS NULL OR p_kolicina <= 0
  THEN
    RAISE EXCEPTION 'Neispravni podaci o majici';
  END IF;

  INSERT INTO public.majice (
    model, boja, velicina, kolicina
  )
  VALUES (
    trim(p_model),
    trim(p_boja),
    trim(p_velicina),
    p_kolicina
  )
  ON CONFLICT (
    lower(trim(model)),
    lower(trim(boja)),
    upper(trim(velicina))
  )
  DO UPDATE SET
    kolicina = public.majice.kolicina
               + EXCLUDED.kolicina;
END;
$function$;
CREATE FUNCTION public.dodaj_majice_sa_minimumom(p_model text, p_boja text, p_velicina text, p_kolicina integer, p_minimalna_kolicina integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF p_model IS NULL OR btrim(p_model) = ''
     OR p_boja IS NULL OR btrim(p_boja) = ''
     OR p_velicina IS NULL OR btrim(p_velicina) = '' THEN
    RAISE EXCEPTION 'Model, boja i veličina su obavezni.';
  END IF;

  IF p_kolicina IS NULL OR p_kolicina < 0
     OR p_minimalna_kolicina IS NULL OR p_minimalna_kolicina < 0 THEN
    RAISE EXCEPTION 'Količina i minimum moraju biti nenegativni cijeli brojevi.';
  END IF;

  INSERT INTO public.majice(
    model, boja, velicina, kolicina, minimalna_kolicina
  )
  VALUES (
    btrim(p_model), btrim(p_boja), btrim(p_velicina),
    p_kolicina, p_minimalna_kolicina
  )
  ON CONFLICT (
    lower(trim(model)),
    lower(trim(boja)),
    upper(trim(velicina))
  )
  DO UPDATE SET
    kolicina = public.majice.kolicina + EXCLUDED.kolicina,
    minimalna_kolicina = EXCLUDED.minimalna_kolicina;
END;
$function$;
ALTER TABLE public.majice ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lager_urednici ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Urednik vidi svoj ID" ON public.lager_urednici FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY "Registrovani mogu citati majice" ON public.majice FOR SELECT TO authenticated USING(true);
CREATE POLICY "Urednici mogu brisati majice" ON public.majice FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.lager_urednici WHERE user_id=(SELECT auth.uid())));
CREATE POLICY "Urednici mogu dodavati majice" ON public.majice FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.lager_urednici WHERE user_id=(SELECT auth.uid())));
CREATE POLICY "Urednici mogu mijenjati majice" ON public.majice FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.lager_urednici WHERE user_id=(SELECT auth.uid()))) WITH CHECK(EXISTS(SELECT 1 FROM public.lager_urednici WHERE user_id=(SELECT auth.uid())));
GRANT ALL ON public.majice TO postgres, anon, authenticated, service_role;
GRANT ALL ON public.lager_urednici TO postgres, service_role;
GRANT SELECT ON public.lager_urednici TO authenticated;
GRANT ALL ON SEQUENCE public.majice_id_seq TO postgres, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.dodaj_majice(text,text,text,integer),public.dodaj_majice_sa_minimumom(text,text,text,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.dodaj_majice(text,text,text,integer),public.dodaj_majice_sa_minimumom(text,text,text,integer,integer) TO postgres,authenticated,service_role;
